"""Central place for paths and shared settings.

Every script and notebook imports from here, so a path or seed is changed in
exactly one place.
"""
from pathlib import Path

# Project root = two levels above this file (src/kbqa/config.py -> project root).
ROOT = Path(__file__).resolve().parents[2]

# --- Source data (CONFIDENTIAL, read-only, git-ignored) ---------------------
RAW_DIR = ROOT / "raw data"          # original folder name kept as supplied
RAW_KBA_FILES = sorted(RAW_DIR.glob("*.json"))

# --- Derived data (git-ignored, regenerated by the pipeline) -------------------
DATA_DIR = ROOT / "data"
PROCESSED_DIR = DATA_DIR / "processed"   # cleaned sections / chunks
QA_DIR = DATA_DIR / "qa"                 # train / val / test QA files

# --- Experiment artefacts ------------------------------------------------------
OUTPUTS_DIR = ROOT / "outputs"           # checkpoints & adapters (git-ignored)
RESULTS_DIR = ROOT / "results"           # metrics CSV/JSON (safe: numbers only)

# Fixed seed for every random operation (splits, sampling, training).
SEED = 42

# The one sentence a model should give when the knowledge base has no answer.
ABSTAIN = "The knowledge base does not contain information to answer this question."
